import{_ as t,C as n,o as s,c as r,j as a,a as l,E as d,a6 as o}from"./chunks/framework.BHBQfcoO.js";const c="/releases/2026.08.0/ncc-1701-asset.webp",u="/releases/2026.08.0/d-pad-component.webp",h="/releases/2026.08.0/base-svg-animation.webm",g="/releases/2026.08.0/shield-bubble.webm",m="/releases/2026.08.0/line-bundling.webp",x=JSON.parse('{"title":"LCARdS 2026.08.0","description":"MSD shapes, shield bubble and line bundling; HA media library; custom sound schemes.","frontmatter":{"version":"2026.08.0","date":"2026-08-06T00:00:00.000Z","status":"released","summary":"MSD shapes, shield bubble and line bundling; HA media library; custom sound schemes.","breaking":true},"headers":[],"relativePath":"releases/2026.08.0.md","filePath":"releases/2026.08.0.md"}'),p={name:"releases/2026.08.0.md"};function f(b,e,y,w,v,k){const i=n("ReleaseMeta");return s(),r("div",null,[e[0]||(e[0]=a("h1",{id:"lcards-2026-08-0",tabindex:"-1"},[l("LCARdS 2026.08.0 "),a("a",{class:"header-anchor",href:"#lcards-2026-08-0","aria-label":'Permalink to "LCARdS 2026.08.0"'},"​")],-1)),d(i),e[1]||(e[1]=o('<p><em>First and foremost, it cannot be said enough - thank you all for using LCARdS, reporting issues, and providing great feedback for improvements!</em></p><p>A rather large release packed full of fixes and features.<br><strong>If you run MSD cards, please read the full notes before upgrading.</strong></p><ul><li>Major MSD features, uplifts and fixes (freeform <code>shapes</code>, &quot;shield generator&quot;, automatic line bundling (&quot;trunk and branch&quot; routing), animation reach into <code>base_svg</code> and now across whole groups of overlays at once...)</li><li>Full HA media library integration and new assets</li><li>Custom sound schemes</li><li>Standardised condition logic across all systems</li><li>Revamped animation preset engine and performance enhancements</li><li>a <em>long</em> list of reliability fixes and other improvements</li></ul><p>There&#39;s also a little treat in the <a href="/core/animations/preset-reference.html">animations</a> and <a href="/core/effects/background-animations/preset-reference.html">backround effects</a> docs for some in-context testing 🖖🏼</p><hr><p><em><strong>Potential (likely) Breaking changes...</strong></em></p><details><summary>...particularly with MSD</summary><ul><li>MSD had a lot of major updates and bug fixes - worthwhile verifying existing MSDs function the way you expect (may require some updates)</li><li>MSD line routing engine has had a huge round of updates, fixes, and enhancements. Line overlays <code>route: auto</code> (the default) now <strong>always</strong> does full pathfinding - including obstacle avoidance, automatic line bundling (see trunking), and crossing avoidance. You may need to adjust some of your settings if line routes are not looking as you expect. See the new <a href="/cards/msd/routing-concepts.html">routing concepts</a> page for more info. This is under refinement so quirks may be present - you can always fall back to traditional/manual line routing if needed.</li><li>Explicit multi-channel <code>route_channels</code> chains are no longer routed in raw declared order - the router now finds the shortest valid ordering automatically, so a chain that was geometrically backwards may render a visibly different (corrected) path after upgrading.</li><li>Button <code>ranges:</code> colours&#39; <code>above</code> boundary is now strict <code>&gt;</code> (previously <code>&gt;=</code>), matching how <code>above</code>/<code>below</code> already behave everywhere else (range colours, <code>while</code> conditions, Rules Engine). If a range config relies on a value landing exactly on the boundary, double-check it still matches the range you expect.</li><li>The <code>grid-stagger</code> animation preset is <strong>removed</strong>. It did not actually stagger elements correctly, so very likely not being used. If you do have <code>preset: grid-stagger</code> in an existing config, migrate to the working <code>stagger-grid</code> (not a drop-in rename - field names and defaults differ.) See the <a href="/core/animations/preset-reference.html#grid-stagger-removed-in-2026-07-x">Animation Preset Reference</a> for the full migration table.</li></ul></details><h2 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h2><h3 id="ha-media-library-integration-and-new-assets" tabindex="-1">HA Media Library Integration and New Assets <a class="header-anchor" href="#ha-media-library-integration-and-new-assets" aria-label="Permalink to &quot;HA Media Library Integration and New Assets&quot;">​</a></h3><p>LCARdS now has full HA media libary integration:</p><ul><li>New <strong>&quot;Browse HA Media&quot;</strong> picker available in card editors for background/texture images, MSD blueprints, and per-card sound overrides.</li><li>LCARdS also publishes its shipped media (images, MSD blueprints, sounds) into the HA media library for use anywhere in HA.</li></ul><p>New Assets:</p><ul><li><code>lcards-msd</code>: new NCC-1701 ship asset for MSDs</li><li><code>lcards-button</code>: fully configurable advanced d-pad component (individually addressable segments)</li></ul><img class="release-shot" alt="New NCC-1701 MSD ship asset" src="'+c+'"><img class="release-shot" alt="Advanced d-pad button component" src="'+u+'"><hr><h3 id="custom-sound-schemes" tabindex="-1">Custom Sound Schemes <a class="header-anchor" href="#custom-sound-schemes" aria-label="Permalink to &quot;Custom Sound Schemes&quot;">​</a></h3><p>You can now edit and save your own sound schemes:</p><ul><li>Pick from LCARdS-shipped sounds, or use your own with HA Media Library integration!</li><li><strong>Save, update, and delete custom sound schemes</strong> directly from the LCARdS Config Panel.</li><li>Per-event sound overrides are now scoped to the scheme you&#39;re editing, instead of one flat list shared by every scheme.</li></ul><hr><h3 id="standardised-comparison-operators-and-between" tabindex="-1">Standardised Comparison Operators: <code>&gt;=</code>, <code>&lt;=</code>, and Between <a class="header-anchor" href="#standardised-comparison-operators-and-between" aria-label="Permalink to &quot;Standardised Comparison Operators: `&gt;=`, `&lt;=`, and Between&quot;">​</a></h3><p>New <code>at_least</code> / <code>at_most</code> (<code>&gt;=</code>/<code>&lt;=</code>) operators, plus inclusive and exclusive <em>&quot;between&quot;</em> are now available everywhere a condition is evaluated - range-based colours, <code>while</code> conditions, Rules Engine, and button <code>ranges:</code> presets. The animation and Rules editors both gained <code>Between (inclusive)</code> / <code>Between (exclusive)</code> options.</p><hr><h3 id="docs-interactive-live-playgrounds" tabindex="-1">Docs: Interactive Live Playgrounds <a class="header-anchor" href="#docs-interactive-live-playgrounds" aria-label="Permalink to &quot;Docs: Interactive Live Playgrounds&quot;">​</a></h3><p>The docs site now has a live, tweakable demo for every built-in animation preset, background animation, and CSS/SVG filter - no HA instance needed:</p><ul><li><a href="/core/animations/preset-reference.html">Animation Preset Reference</a> - animation presets</li><li><a href="/core/effects/background-animations/preset-reference.html">Background Animation Preset Reference</a> - canvas presets</li><li><a href="/core/effects/filters.html">Filters Reference</a> - CSS/SVG filter types</li></ul><p>Each demo has real sliders/dropdowns/colour pickers, a live-updating YAML snippet you can copy straight into your config, and Replay/Reset-to-Defaults controls. Building these surfaced (and fixed) several real bugs - see below.</p><hr><h3 id="animation-engine-performance-enhancements-editor-preset-config-validation-383" tabindex="-1">Animation Engine: Performance Enhancements, Editor &amp; Preset Config Validation (<a href="https://github.com/snootched/lcards/issues/383" target="_blank" rel="noreferrer">#383</a>) <a class="header-anchor" href="#animation-engine-performance-enhancements-editor-preset-config-validation-383" aria-label="Permalink to &quot;Animation Engine: Performance Enhancements, Editor &amp; Preset Config Validation ([#383](https://github.com/snootched/lcards/issues/383))&quot;">​</a></h3><ul><li>Huge performance gains in calculation-heavy animations (contour, plasma)</li><li>Animation presets are now schema validated, catching bad configs before they cause confusing behavior.</li><li>One consistent, schema-driven editor replaces the old bespoke preset-by-preset UI. Includes collapsible guides with YAML samples, added standard LCARdS colour pickers along with proper token resolution, and a proper code editor for advanced params.</li><li>Embedded links on each animation to the preset documentation (which also has an animation playground to play with settings)</li><li><code>motionpath</code> for paths went from a non-functional placeholder to a real, working preset with a new &quot;tracer shape&quot; mode</li><li>Fixed a batch of presets that silently misbehaved (staggering, timelines, sequences, transforms); removed <code>border-pulse</code>/<code>scan-line</code>, which never worked.</li><li>New <code>solid</code> background-animation preset allowing for a basic tint layer. Useful for use behind your MSD blueprint without tinting the artwork itself.</li><li>The animation editor now surfaces <code>map_range</code> - a powerful entity-reactive duration/delay/preset params. This is to raise your awareness for this YAML-only configuration.</li></ul><h2 id="msd" tabindex="-1">MSD <a class="header-anchor" href="#msd" aria-label="Permalink to &quot;MSD&quot;">​</a></h2><h3 id="msd-studio-base-svg-element-animations-easier-editing-layering-backgrounds-state-based-line-colour-383" tabindex="-1">MSD Studio: <code>base_svg</code> Element Animations, Easier Editing, Layering, Backgrounds &amp; State-Based Line Colour (<a href="https://github.com/snootched/lcards/issues/383" target="_blank" rel="noreferrer">#383</a>) <a class="header-anchor" href="#msd-studio-base-svg-element-animations-easier-editing-layering-backgrounds-state-based-line-colour-383" aria-label="Permalink to &quot;MSD Studio: `base_svg` Element Animations, Easier Editing, Layering, Backgrounds &amp; State-Based Line Colour ([#383](https://github.com/snootched/lcards/issues/383))&quot;">​</a></h3><p>The MSD Studio got a ground-up pass:</p><ul><li>Animations can now target elements inside your blueprint SVG itself. You can animate portions of the <code>base_svg</code> image if you want. You can even match multiple as one definition (ie. target all <code>&lt;path&gt;</code> at once)</li></ul>',34)),e[2]||(e[2]=a("p",null,[a("video",{class:"release-shot",src:h,title:"Animating elements of an MSD blueprint SVG",autoplay:"",loop:"",muted:"",playsinline:""})],-1)),e[3]||(e[3]=o('<ul><li>Layering (z-index ordering <a href="https://github.com/snootched/lcards/issues/383" target="_blank" rel="noreferrer">#383</a>): controls, lines, and backgrounds now paint in the order you configure.</li><li>MSD now supports the standard background animation layer present in other cards. You can add background animations/images behind your blueprint. You can also choose to hide the blueprint outline if you only want to use it to derive anchor points.</li><li>Lines are now state-aware! Change colour based on entity state (like buttons/elbows already do), use colour templates in line styles, and markers can inherit their line&#39;s colour/opacity and stay aligned to a thick stroke&#39;s edge.</li><li>Controls can attach directly to other controls, with a visual 9-point picker showing exactly where the attachment lands.</li><li>Configured attachment point is distinguished visually so you know exactly where the overlay is connected.</li></ul><hr><h3 id="new-msd-card-level-bulk-overlay-animations" tabindex="-1">(New) MSD: Card-Level Bulk Overlay Animations <a class="header-anchor" href="#new-msd-card-level-bulk-overlay-animations" aria-label="Permalink to &quot;(New) MSD: Card-Level Bulk Overlay Animations&quot;">​</a></h3><p>Building on <code>base_svg</code> element animations above - one animation declaration can now target a whole <em>group</em> of overlays at once, instead of repeating the same config on each one:</p><ul><li>New <code>msd.animations:</code> - define an animation once, at the card level, and point it at a CSS selector matching multiple overlays. Perfect for something like Shield Bubble&#39;s segments (up to 16 individual polylines) - animate all of them together (draw-on, marching ants, pulse, etc.) with a single entry.</li><li>The animation editor&#39;s target picker gained ready-made bulk-select options - <strong>&quot;All Lines/Shapes/Controls overlays,&quot;</strong> and an automatic <strong>&quot;All <code>&lt;prefix&gt;_*</code> overlays&quot;</strong> option for any group of overlays sharing a naming convention (e.g. Shield Bubble&#39;s <code>shield_*</code> segments) - no manual CSS selector writing required.</li></ul><hr><h3 id="new-msd-shape-overlays-free-draw-shapes-to-create-walls-rooms-zones-on-the-canvas-389" tabindex="-1">(New) MSD Shape Overlays: Free-draw shapes to create walls, rooms &amp; zones on the Canvas (<a href="https://github.com/snootched/lcards/issues/389" target="_blank" rel="noreferrer">#389</a>) <a class="header-anchor" href="#new-msd-shape-overlays-free-draw-shapes-to-create-walls-rooms-zones-on-the-canvas-389" aria-label="Permalink to &quot;(New) MSD Shape Overlays: Free-draw shapes to create walls, rooms &amp; zones on the Canvas ([#389](https://github.com/snootched/lcards/issues/389))&quot;">​</a></h3><p>A brand new <code>shape</code> overlay type for freeform geometry, with the same styling power as the routable line overlays:</p><ul><li>Starting with three shape primitives: <strong>polyline</strong> (free-form lines) <strong>rect</strong>, and <strong>circle</strong>/ellipse - with dashed strokes, gradients, markers, and live state-based fill colour.</li><li>Draw directly on the canvas with new toolbar tools, live preview, and grid-snapping, then drag points/handles to reshape.</li><li>Lines can attach to shapes - corners, edges, or individual points - shown as clickable connection points in Connect Mode.</li><li>Full animation and Rules Engine support like any other overlay, a new <strong>Shapes</strong> tab, and a <a href="/cards/msd/shape-overlay.html">reference doc</a>.</li></ul><hr><h3 id="new-msd-shield-bubble-389" tabindex="-1">(New) MSD: Shield Bubble (<a href="https://github.com/snootched/lcards/issues/389" target="_blank" rel="noreferrer">#389</a>) <a class="header-anchor" href="#new-msd-shield-bubble-389" aria-label="Permalink to &quot;(New) MSD: Shield Bubble ([#389](https://github.com/snootched/lcards/issues/389))&quot;">​</a></h3><p>Buidling on the new <code>shape</code> overlay type - a new <strong><em>&quot;Suggest Shield Bubble&quot;</em></strong> tool in the Shapes tab will trace your ship&#39;s hull automatically and generates a shield outline. You can create one continuous path, or segment into any number of your choice - no manual point-placing required:</p><ul><li>Adjustable offset radius, corner-preserving simplification, and a <strong>roundness</strong> slider (blends toward a smooth oval) - all live-previewed and instantly tunable as you drag.</li><li><strong>Sections mode</strong> shares exact seams with no visible gaps, plus a start-angle control to rotate where the boundaries fall.</li><li>Once saved as overlays - you can then edit them in same fashion as lines. Configure styles and animations, you can drag the points to new positions on the canvas and even add more points anywhere along the polyline.</li></ul>',13)),e[4]||(e[4]=a("p",null,[a("video",{class:"release-shot",src:g,title:"Suggest Shield Bubble tracing a ship hull",autoplay:"",loop:"",muted:"",playsinline:""})],-1)),e[5]||(e[5]=o('<hr><h3 id="new-msd-automatic-line-bundling-trunk-and-branch-routing" tabindex="-1">(New) MSD: Automatic Line Bundling - &quot;Trunk and Branch&quot; Routing <a class="header-anchor" href="#new-msd-automatic-line-bundling-trunk-and-branch-routing" aria-label="Permalink to &quot;(New) MSD: Automatic Line Bundling - &quot;Trunk and Branch&quot; Routing&quot;">​</a></h3><img class="release-shot" alt="MSD lines bundled into shared trunks" src="'+m+'"><p>Lines that route and travel close to each other can now bundle together into a shared corridor and branch apart where their destinations actually diverge - like traces on a circuit board.</p><ul><li>Works for any line with route mode <code>auto</code> (the default), <code>smart</code>, or <code>grid</code></li><li>Lines are also discouraged from cutting across each other&#39;s paths where a reasonable alternative exists, and corner rounding is now aware of neighbouring lines so two bundled lines&#39; corners no longer overlap or squash each other.</li><li>New per-line <code>corner_radius_mode</code> (<code>auto</code>/<code>forced</code>) lets you choose between letting the router shrink a corner&#39;s desired radius to avoid an unnecessary detour or crossing (the recommended default), or always reserving full room for your configured <code>corner_radius</code> regardless.</li><li>Corner rounding now also accounts for a line&#39;s own <code>style.width</code> - thicker lines get a correctly tighter effective radius near their neighbours instead of rendering a squared-off inner edge.</li><li>Explicit routing <code>channels</code> still work exactly as before, and now share the same bundling/lane machinery as automatic bundling, so the two compose naturally.</li><li>New <strong>Routing Grid</strong> and <strong>Discovered Trunks</strong> debug overlays (with toolbar toggles) in MSD Studio&#39;s canvas make it easy to see what the router decided.</li><li><strong>Tip:</strong> router grid size is determined automatically from your view_box dimensions. You can adjust this to change the coarseness of the router resolution.</li><li>Studio&#39;s Routing tab reorganized, has more info, tips and explainers.</li><li>See new <a href="/cards/msd/routing.html">Routing &amp; Channels</a> reference page, and a brand new <a href="/cards/msd/quick-start.html">MSD Quick Start</a> guide walking through building your first MSD.</li></ul><hr><h3 id="msd-studio-interaction-editing-polish-389" tabindex="-1">MSD Studio: Interaction &amp; Editing Polish (<a href="https://github.com/snootched/lcards/issues/389" target="_blank" rel="noreferrer">#389</a>) <a class="header-anchor" href="#msd-studio-interaction-editing-polish-389" aria-label="Permalink to &quot;MSD Studio: Interaction &amp; Editing Polish ([#389](https://github.com/snootched/lcards/issues/389))&quot;">​</a></h3><details><summary> A large batch of quality-of-life fixes and additions to the Studio canvas itself: </summary><ul><li>New <strong>Edit Mode</strong> toggle (and <code>E</code> hotkey) for directly dragging/resizing controls, shapes, and channels on the canvas, with a live coordinate/dimension readout while you drag.</li><li>Click-and-drag drawing for shapes, routing channels, and <strong>Place Control</strong> - size them directly on the canvas instead of opening a form with a fixed default size.</li><li>Click-to-insert a new point at the midpoint of any line or shape segment, instead of only being able to append points via drag or a form.</li><li>Per-waypoint corner radius for manual-routed lines: [x, y, radius] waypoint override (round or bevel) - Studio gets a Radius field + canvas drag handle per corner.</li><li>Bulk Edit Style: multi-select shapes/lines and restyle all at once (diff-based, only changed fields applied).</li><li>Added per-overlay <code>locked</code> flag for controls/shapes (locks changes in the editor-only, no runtime effect).</li><li>Fixed resize handles that could drift or appear to get permanently &quot;stuck&quot; while shrinking a control, shape, or channel.</li><li>Fixed Escape not reliably cancelling an in-progress draw, double-click adding a spurious extra point when finishing a polyline (Enter now also finishes one, alongside double-click), and shapes/lines staying visually selected after clicking empty canvas.</li><li>Toolbar reorganized into labeled groups (Tools/Interaction/View/Overlays); raised the canvas zoom ceiling from 400% to 1000%.</li><li>A round of dialog-scrolling, zoom-fit, and layout-overflow fixes across the Base SVG, Controls, Lines, Shapes, and Anchors tabs.<br> -Editing a control or line no longer duplicates it - edits now update the original in place as expected.</li><li>Live preview while editing a line now shows the real rendered result</li><li>a general UX refresh - more organized and visible action bar, more consistent dialog styling, additional action buttons on items (like duplicate)</li><li>Updated anchor harvesting, now supports named <code>&lt;circle&gt;</code>/<code>&lt;text&gt;</code>/<code>&lt;g&gt;</code>/<code>&lt;ellipse&gt;</code>/<code>&lt;rect&gt;</code> elements in your SVG.</li><li>New toggles let you turn either anchor source off - handy for a noisy, auto-numbered SVG, or an asset where the computed landmarks aren&#39;t useful.</li></ul></details><h2 id="reliability-improvements" tabindex="-1">Reliability Improvements <a class="header-anchor" href="#reliability-improvements" aria-label="Permalink to &quot;Reliability Improvements&quot;">​</a></h2><details><summary>Many reliability improvements on existing features...</summary><ul><li>Alert-mode and entity-driven colours now update properly and in the right order (elimated flickering/racing)</li><li>Entities bound to a specific <code>attribute</code> (e.g. brightness) now update immediately when just that <strong>attribute</strong> changes - previously triggering only fired on a full <strong>state</strong> change.</li><li>Fixed <code>while</code> conditions with both an <code>above</code> and <code>below</code> bound only ever checking one of the two, not both.</li><li>Fixed animations tied to entity-change triggers occasionally duplicating instead of cleanly replacing themselves. (<a href="https://github.com/snootched/lcards/issues/386" target="_blank" rel="noreferrer">#386</a>)</li><li>Cards embedded in MSD <code>control</code> overlays now reliably stay in sync with Home Assistant - some setups (nested config, template-only entities, dynamically-matched entities) could previously stop updating after the first paint. A card&#39;s own <code>visibility:</code> condition also now works correctly when embedded as an MSD control, matching how it behaves everywhere else. (<a href="https://github.com/snootched/lcards/issues/387" target="_blank" rel="noreferrer">#387</a>) Visibility tab is not present in the editor due to HA limitations - just add visibility conditions via YAML.</li><li>MSD attachment/routing fixes: attachment sides (<code>top</code>/<code>bottom</code>/<code>left</code>/<code>right</code>) now resolve correctly instead of silently falling back to center; shape fill colours now update live along with their stroke colour; lines now correctly honor <code>route_hint</code>/<code>route_hint_last</code> in all routing modes; and routing now works correctly with custom or negative-origin <code>view_box</code> coordinates.</li><li>MSD line-routing correctness verified by automated test suite (over 130 tests):</li><li>Fixed a first-load-only false positive where MSD&#39;s heavier post-routing initialization could trip the background animation system&#39;s cold-start safety check, forcing an unnecessary 5-30 minute animation recovery backoff.</li><li>Fixed a colour-configuration bug where two different overlays could end up sharing the same underlying colour object, causing an edit to one to unexpectedly bleed into the other.</li><li>Fixed a long-standing bug where MSD&#39;s coordinate system (<code>view_box</code>) could be computed inconsistently, causing overlays/anchors to be positioned using the wrong dimensions on some cards. Also fixed anchors misplacing themselves inside rotated/transformed SVG groups.</li></ul></details><h2 id="other-fixes-improvements" tabindex="-1">Other Fixes &amp; Improvements <a class="header-anchor" href="#other-fixes-improvements" aria-label="Permalink to &quot;Other Fixes &amp; Improvements&quot;">​</a></h2><details><summary>..and a slew of other bug fixes and small improvements</summary><ul><li>New validation for background-animation and filter values, catching real config mistakes (e.g. an opacity value outside 0–1) and powering the new live docs demos.</li><li>Fixed the <code>level</code> texture/background effect rendering <code>down</code>/<code>left</code> identically to <code>up</code>/<code>right</code> - all four directions now render correctly.</li><li>The <code>grid</code> background animation&#39;s <code>diagonal</code>, <code>hexagonal</code>, and <code>dots</code> patterns are now properly exposed in the editor, along with their sizing options.</li><li>Fixed the <code>image</code> background animation&#39;s docs, which referenced the wrong config fields.</li><li>Corrected several other doc inaccuracies: shape-texture wave directions, the <code>cascade</code> preset&#39;s timing units, and <code>grid</code> pattern documentation.</li><li>Removed the unused MSD <code>filter_preset</code> system and the long-dead <code>msd.debug</code> config option - both had zero effect on anything for some time.</li><li>Fixed colour resolution for theme tokens and CSS variables used inside SVG filters.</li><li>Fixed sound/connectivity settings occasionally reading stale data on dashboard tabs that never opened the Config Panel.</li><li>Fixed loading spinners rendering invisible across 13 places in the editor/panels (an underlying HA component was replaced).</li><li>Fixed a <code>&#39;none&#39;</code> sound scheme playing the first registered scheme instead of staying silent.</li><li>Fixed the <code>march</code> (marching ants) animation preset producing a visible snap/jump at each loop restart on multi-segment dash patterns. Proper length is now calculated for seamless looping.</li><li>Removed a stale bundled SVG variant no longer shipped.</li><li>Elbow: Added interactive: false flag (suppress hover color/animation, tap/hold still work) and a style.cursor override.</li><li>Slider: Fixed jumpback: slider no longer resyncs from HASS mid-drag, so a poll/attribute update while dragging can&#39;t snap the value back before your own service call lands. (<a href="https://github.com/snootched/lcards/issues/392" target="_blank" rel="noreferrer">#392</a>)</li><li>Slider: Fixed vertical-mode value markers being offset by a nudge that was only meant for the horizontal preset&#39;s cross-axis.</li></ul></details><hr><p>All changes: <a href="https://github.com/snootched/lcards/compare/2026.07.02.1...2026.08.0" target="_blank" rel="noreferrer">2026.07.02.1...2026.08.0</a></p>',14))])}const _=t(p,[["render",f]]);export{x as __pageData,_ as default};
